INSERT INTO `jobs` VALUES (2,'IT Technician (Full Time)','IT Dept','Full-time','Active','lorem ipsum',NULL,NULL,NULL,'2026-08-03 04:04:44',2,1,'On-site',NULL,NULL,NULL,NULL,0),(6,'Senior Backend Engineer','Engineering','Full-time','Active','We are looking for an experienced Senior Backend Engineer to architect and scale our core APIs. You will work closely with the product team to deliver high-performance microservices. Requirements: 5+ years of experience with Node.js and PostgreSQL, deep understanding of cloud infrastructure (AWS), and a proven track record of designing scalable systems.',NULL,NULL,NULL,'2026-08-03 09:43:17',2,1,'Hybrid',NULL,NULL,NULL,NULL,1),(7,'Product Marketing Manager','Marketing','Full-time','Active','Seeking a creative and strategic Product Marketing Manager to lead our go-to-market initiatives. You will craft compelling messaging, conduct market research, and drive product adoption. Requirements: 3+ years in B2B SaaS marketing, excellent copywriting skills, and experience running successful product launches.',NULL,NULL,NULL,'2026-08-03 09:43:43',2,1,'Remote',NULL,NULL,NULL,NULL,1),(8,'UI/UX Designer','Design','Contract','Active','Join our design team to craft intuitive and visually stunning user experiences for our web and mobile applications. Requirements: Proficiency in Figma, a strong portfolio showcasing complex problem-solving, and a solid understanding of accessibility standards.',NULL,NULL,NULL,'2026-08-03 09:44:14',2,1,'Remote',NULL,NULL,NULL,NULL,0),(9,'Customer Success Specialist','Customer Support','Full-time','Active','We need an empathetic and proactive Customer Success Specialist to help our clients achieve their business goals using our platform. Requirements: 2+ years in a customer-facing role, stellar written and verbal communication skills, and the ability to troubleshoot basic technical issues.',NULL,NULL,NULL,'2026-08-03 09:44:37',2,1,'Hybrid',NULL,NULL,NULL,NULL,1),(10,'Senior Data Scientist','Data & Analytics','Full-time','Active','Dive into complex datasets to extract actionable insights and build predictive models that drive our business strategy forward. Requirements: Master\'s degree in a quantitative field, expertise in Python and SQL, and hands-on experience with modern Machine Learning frameworks (TensorFlow, PyTorch).',NULL,NULL,NULL,'2026-08-03 09:45:06',2,1,'On-site',NULL,NULL,NULL,NULL,0),(11,'Talent Acquisition Manager','Human Resources','Full-time','Active','Lead our hiring efforts and help us scale our global team. You will manage the full recruitment lifecycle and build strong talent pipelines. Requirements: 4+ years of full-cycle recruiting experience (preferably in tech), strong interviewing skills, and familiarity with AI-driven ATS platforms.',NULL,NULL,NULL,'2026-08-03 09:45:36',2,1,'Hybrid',NULL,NULL,NULL,NULL,1),(12,'Enterprise Account Executive','Sales','Full-time','Active','Drive revenue growth by identifying, negotiating, and closing complex enterprise deals. Requirements: 5+ years of quota-carrying B2B sales experience, exceptional presentation skills, and a history of consistently exceeding sales targets.',NULL,NULL,NULL,'2026-08-03 09:46:04',2,1,'Remote',NULL,NULL,NULL,NULL,1),(13,'Technical Writer','Documentation','Part-time','Active','Create clear, accurate, and comprehensive documentation for our developer API and internal tools. Requirements: Ability to translate complex technical concepts into easy-to-read guides, experience with Markdown, and a basic understanding of RESTful APIs.',NULL,NULL,NULL,'2026-08-03 09:46:40',2,1,'Remote',NULL,NULL,NULL,NULL,0),(14,'Financial Controller','Operations','Full-time','Active','Facilitate agile ceremonies, remove blockers, and ensure the timely delivery of cross-functional software projects. Requirements: Certified Scrum Master (CSM) or equivalent, 3+ years of project management experience, and exceptional organizational abilities.',NULL,NULL,NULL,'2026-08-03 09:47:00',2,1,'Hybrid',NULL,NULL,NULL,NULL,1),(15,'Junior Full-Stack Developer','Engineering','Internship','Active','We are looking for a motivated Junior Full-Stack Developer to join our Engineering team. You will be responsible for developing, testing, and maintaining both web and mobile applications. You will work closely with our UI/UX designers to implement sleek, minimalist interfaces and collaborate with senior developers to integrate existing AI tools and build robust backend architectures.\r\n\r\nKey Responsibilities\r\n\r\nDevelop and maintain progressive web apps (PWAs) and cross-platform mobile applications.\r\n\r\nDesign and manage relational databases for secure data handling.\r\n\r\nTranslate UI/UX wireframes into functional, highly responsive, and modern user interfaces.\r\n\r\nIntegrate third-party APIs and existing AI tools to enhance application functionality.\r\n\r\nCollaborate with project managers and fellow developers in an agile environment.\r\n\r\nRequirements\r\n\r\nDegree or Diploma in Software Engineering, Information Technology, or a related field.\r\n\r\nProficiency in Java (EJB, JSP) and PHP for backend development.\r\n\r\nStrong frontend skills using HTML5, CSS3, and JavaScript, with an eye for sleek, modern design.\r\n\r\nExperience with Flutter for mobile application development.\r\n\r\nSolid understanding of relational databases, specifically MySQL.\r\n\r\nFamiliarity with version control systems (Git/GitHub).\r\n\r\nExcellent problem-solving skills and the ability to work independently in a hybrid environment.',NULL,NULL,NULL,'2026-08-04 02:10:16',4,2,'Hybrid',NULL,NULL,NULL,NULL,1),(18,'IT Executive','IT','Full-time','Active','Key Responsibilities\r\n\r\n• Manage and support company servers, network infrastructure, and cloud environments (AWS/Azure).\r\n• Monitor system performance, availability, and security.\r\n• Troubleshoot and resolve infrastructure, network, and system-related issues.\r\n• Administer Windows and Linux servers, including Active Directory, DNS, and DHCP.\r\n• Support cloud services, backups, disaster recovery, and business continuity activities.\r\n• Provide IT support for office users, including laptops, desktops, printers, and network connectivity.\r\n• Coordinate with vendors for system maintenance, upgrades, and IT projects.\r\n• Maintain IT documentation, asset records, and software licenses.\r\n• Travel to KL office or data center when required.\r\n\r\nRequirements\r\n\r\n• Diploma or Bachelor\'s Degree in IT, Computer Science, or related field.\r\n• Minimum 2 years of experience in IT infrastructure, system administration, or cloud support.\r\n• Basic knowledge of AWS and/or Azure.\r\n• Experience with Windows and Linux servers.\r\n• Good understanding of networking concepts (TCP/IP, DNS, DHCP, VPN).\r\n• Strong troubleshooting and problem-solving skills.\r\n• Able to work independently and as part of a team.\r\n\r\nNice to Have\r\n\r\n• VMware or virtualization experience.\r\n• Docker or Kubernetes exposure.\r\n• Scripting knowledge (PowerShell, Bash, Python).\r\n• Experience with monitoring and backup solutions.',NULL,NULL,NULL,'2026-08-20 07:25:55',9,3,'On-site',NULL,NULL,NULL,NULL,1),(20,'HR Executive','HR','Full-time','Active','Key responsibilities\r\n\r\n\r\n- Support the full employee lifecycle, including recruitment, onboarding, training and development, and offboarding\r\n\r\n- Assist with the preparation of job descriptions, job postings and recruitment materials to attract qualified candidates\r\n\r\n- Conduct preliminary interviews and coordinate the recruitment process with hiring managers\r\n\r\n- Maintain accurate employee records and ensure compliance with data protection regulations\r\n\r\n- Support the coordination and delivery of employee training and development programmes\r\n\r\n- Assist with the organisation and coordination of company events, team-building activities and employee engagement initiatives\r\n\r\n- Provide administrative support to the HR team, including maintaining HR databases and filing systems\r\n\r\n- Support the implementation and communication of HR policies and procedures\r\n\r\n- Handle employee queries and concerns relating to HR matters, demonstrating empathy and professionalism\r\n\r\n- Assist with payroll administration and ensure accurate and timely processing of employee information\r\n\r\n- Support HR compliance activities and ensure adherence to relevant employment legislation\r\n\r\n- Contribute to projects and special initiatives as assigned by the HR Manager or Senior HR staff\r\n\r\n\r\n\r\nWhat we\'re looking for\r\n\r\n\r\n- A Secondary School Certificate or equivalent qualification; a professional HR qualification (such as CIPD, SHRM or equivalent) is advantageous\r\n\r\n- Proven experience in an HR role, ideally in an HR Executive or similar administrative capacity\r\n\r\n- Strong knowledge of HR practices, employment law and best practices in Malaysia\r\n\r\n- Excellent organisational and time management skills with the ability to manage multiple tasks simultaneously\r\n\r\n- Exceptional communication and interpersonal skills with the ability to interact effectively with employees at all levels\r\n\r\n- Proficiency in Microsoft Office applications and HR management systems\r\n\r\n- A thorough understanding of recruitment and employee relations processes\r\n\r\n- Demonstrated commitment to maintaining confidentiality and handling sensitive information with discretion\r\n\r\n- A proactive, problem-solving mindset with the ability to work both independently and collaboratively\r\n\r\n- Strong attention to detail and accuracy in all administrative and record-keeping activities\r\n\r\n- Flexibility and adaptability in response to changing business needs',NULL,NULL,NULL,'2026-08-20 08:44:42',9,3,'On-site',NULL,NULL,NULL,NULL,1),(21,'CF Executive','CF','Full-time','Active','test',NULL,NULL,NULL,'2026-08-28 09:15:38',9,3,'Hybrid',NULL,NULL,NULL,NULL,0),(22,'Senior Backend Engineer','','Full-time','Active','asdasd',NULL,NULL,NULL,'2026-09-08 03:26:08',2,1,'Hybrid',NULL,NULL,NULL,NULL,0),(23,'Network Engineer','Engineering','Contract','Active','We are looking for a motivated Network Engineer to join our team. You will be responsible for designing, implementing, and maintaining our network infrastructure to ensure optimal performance, security and reliability.','• Design, configure and maintain network systems and infrastructure\n• Monitor network performance and troubleshoot issues\n• Implement security measures and ensure network reliability','• Bachelor\'s degree in Computer Science, Networking or related field\n• 2+ years experience in network administration or engineering\n• Cisco CCNA/CCNP or CompTIA Network+ certification is a plus','• Competitive compensation & allowances\n• Health & dental coverage\n• Continuous learning & professional certification sponsorship','2026-09-09 03:11:53',44,NULL,'On-site','Kuala Lumpur',4500,7500,NULL,0),(25,'Frontend Developer','Engineering','Part-time','Active','Looking for a creative and detail-oriented Frontend Developer to build beautiful, responsive web applications with modern frontend frameworks and smooth user experiences.','• Build interactive user interfaces with clean HTML, CSS and JavaScript\n• Ensure responsive design across all mobile and desktop devices\n• Optimize web performance and load times','• Experience with JavaScript, CSS3, and React or Vue.js\n• Solid understanding of UX/UI best practices\n• Good communication and teamwork abilities','• Flexible hours\n• Remote-friendly options\n• Modern work equipment provided','2026-09-04 03:11:53',45,NULL,'On-site','Kuala Lumpur',3500,5500,NULL,0),(26,'Marketing Executive','Marketing','Full-time','Active','Join our dynamic creative team as a Marketing Executive. You will spearhead digital campaigns, content creation, social media strategy, and brand growth across Southeast Asia.','• Plan and execute digital marketing and social media campaigns\n• Create engaging promotional copy and visual content\n• Analyze marketing analytics to optimize ROI','• Diploma/Degree in Marketing, Mass Comm or related\n• Experience with social media ads and Google Analytics\n• Creative mindset with excellent written communication','• Hybrid work arrangement (2 days WFH)\n• Monthly wellness budget\n• Team bonding events and dinners','2026-09-08 03:11:53',46,NULL,'Hybrid','Kuala Lumpur',3000,4800,NULL,0);
