INSERT INTO `resume_builds` VALUES (1,20,'Marketing Executive','{\"target_title\":\"Marketing Executive\",\"experience\":[{\"company\":\"brightbeam\",\"role\":\"it manager\",\"duration\":\"2022 - 2024\",\"notes\":\"managed security test, pentest, website development\"}],\"education\":[{\"school\":\"universiti kuala lumpur\",\"degree\":\"degree in software engineering\",\"year\":\"2021\"}],\"skills\":\"PHP, HTML, PYTHON, CSS, JAVA, JS\",\"extra_notes\":\"\",\"is_fresh_grad\":false,\"full_name\":\"Test 5\",\"contact_email\":\"mommytobabydimples@lellol.dev\",\"contact_phone\":\"01116208644\",\"location\":\"Kuala Lumpur, Malaysia\"}','{\"summary\":\"Results-driven IT professional and Software Engineering graduate transitioning to a Marketing Executive role, leveraging a strong technical foundation in web development and digital security. Experienced in managing end-to-end website development and executing robust security testing to optimize online platforms. Skilled in utilizing programming languages such as Python, PHP, and JavaScript to support and enhance digital infrastructure.\",\"experience\":[{\"company\":\"brightbeam\",\"role\":\"it manager\",\"duration\":\"2022 - 2024\",\"bullets\":[\"Directed comprehensive website development initiatives, ensuring optimal performance, seamless user experience, and robust digital presence.\",\"Managed rigorous security testing and penetration testing (pentesting) protocols to safeguard digital assets and identify system vulnerabilities.\",\"Oversaw technical operations and web infrastructure to support organizational goals and maintain high platform reliability.\"]}],\"education\":[{\"degree\":\"Degree in Software Engineering\",\"school\":\"Universiti Kuala Lumpur\",\"year\":\"2021\"}],\"skills\":[\"PHP\",\"HTML\",\"Python\",\"CSS\",\"Java\",\"JavaScript\"],\"achievements\":[],\"full_name\":\"Test 5\",\"contact_email\":\"mommytobabydimples@lellol.dev\",\"contact_phone\":\"01116208644\",\"location\":\"Kuala Lumpur, Malaysia\"}',