 manager\",\"duration\":\"2022 - 2024\",\"notes\":\"managed security test, pentest, website development\"}],\"education\":[{\"school\":\"universiti kuala lumpur\",\"degree\":\"degree in software engineering\",\"year\":\"2021\"}],\"skills\":\"PHP, HTML, PYTHON, CSS, JAVA, JS\",\"extra_notes\":\"\",\"is_fresh_grad\":false,\"full_name\":\"Test 5\",\"contact_email\":\"mommytobabydimples@lellol.dev\",\"contact_phone\":\"01116208644\",\"location\":\"Kuala Lumpur, Malaysia\"}','{\"summary\":\"Technical IT professional with a background in software engineering and web management, seeking to leverage technical expertise in web development into a Marketing Executive role. Experienced in overseeing website development and managing technical security processes. Proficient in key web technologies and programming languages to support digital initiatives.\",\"experience\":[{\"company\":\"Brightbeam\",\"role\":\"IT Manager\",\"duration\":\"2022 - 2024\",\"bullets\":[\"Oversaw website development projects, ensuring functional design and reliable platform performance.\",\"Managed comprehensive security testing and penetration testing to protect systems and user data.\",\"Coordinated technical operations and platform maintenance to support organizational standards.\"]}],\"education\":[{\"degree\":\"Degree in Software Engineering\",\"school\":\"Universiti Kuala Lumpur\",\"year\":\"2021\"}],\"skills\":[\"PHP\",\"HTML\",\"Python\",\"CSS\",\"Java\",\"JavaScript\"],\"achievements\":[],\"full_name\":\"Test 5\",\"contact_email\":\"mommytobabydimples@lellol.dev\",\"contact_phone\":\"01116208644\",\"location\":\"Kuala Lumpur, Malaysia\"}','2026-09-14 07:53:35'),(4,20,'Marketing Executive','{\"target_title\":\"Marketing Executive\",\"experience\":[{\"company\":\"brightbeam\",\"role\":\"it manager\",\"duration\":\"2022 - 2024\",\"notes\":\"managed security test, pentest, website development\"}],\"education\":[{\"school\":\"universiti kuala lumpur\",\"degree\":\"degree in software engineering\",\"year\":\"2021\"}],\"skills\":\"PHP, HTML, PYTHON, CSS, JAVA, JS\",\"extra_notes\":\"\",\"is_fresh_grad\":false,\"full_name\":\"Test 5\",\"contact_email\":\"mommytobabydimples@lellol.dev\",\"contact_phone\":\"01116208644\",\"location\":\"Kuala Lumpur, Malaysia\"}','{\"summary\":\"Technically adept professional with a background in IT management and software engineering transitioning into a Marketing Executive role. Leverages expertise in website development, web technologies, and technical project management to support digital marketing strategies and optimize online user experiences. Skilled in leveraging programming languages such as HTML, CSS, and JavaScript to enhance web platforms.\",\"experience\":[{\"company\":\"Brightbeam\",\"role\":\"IT Manager\",\"duration\":\"2022 - 2024\",\"bullets\":[\"Managed end-to-end website development projects, ensuring strong functionality, performance, and user interface design.\",\"Oversee digital security operations, coordinating comprehensive security testing and penetration tests to protect web infrastructure.\",\"Collaborated with cross-functional teams to streamline web processes and support organization-wide digital assets.\"]}],\"education\":[{\"degree\":\"Degree in Software Engineering\",\"school\":\"Universiti Kuala Lumpur\",\"year\":\"2021\"}],\"skills\":[\"PHP\",\"HTML\",\"Python\",\"CSS\",\"Java\",\"JavaScript\"],\"achievements\":[],\"full_name\":\"Test 5\",\"contact_email\":\"mommytobabydimples@lellol.dev\",\"contact_phone\":\"01116208644\",\"location\":\"Kuala Lumpur, Malaysia\"}','2026-09-14 07:53:52');
